const data = $input.first().json;
const msg = data.body?.prompt 
  ?? data.prompt 
  ?? data.chatInput 
  ?? data.input 
  ?? data.message 
  ?? 'una sedia medievale';

const sessionId = data.body?.session_id 
  ?? data.session_id 
  ?? 'test_' + Date.now().toString();

return [{ json: { prompt: msg.trim(), session_id: sessionId } }];

// L'output dell'AI Agent arriva in output.text o output.output
const agentOutput = $input.first().json.output 
  ?? $input.first().json.text 
  ?? $input.first().json.content
  ?? '';

const sessionId = $('Estrai prompt + session_id').first().json.session_id;

let parsed;
try {
  const clean = agentOutput.replace(/```json|```/gi, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('Nessun JSON trovato');
  parsed = JSON.parse(match[0]);
} catch(e) {
  // Fallback: usa il testo grezzo come prompt FLUX
  console.log('JSON parse fallito, uso fallback. Output:', agentOutput.substring(0, 200));
  parsed = {
    flux_prompt: `${agentOutput.substring(0, 200)}, white background, studio lighting, product photography`,
    object_name: 'object',
    style_tags: ''
  };
}

if (!parsed.flux_prompt) {
  throw new Error(`flux_prompt mancante. Parsed: ${JSON.stringify(parsed)}`);
}

return [{ json: {
  flux_prompt: parsed.flux_prompt,
  object_name: parsed.object_name ?? 'object',
  style_tags: parsed.style_tags ?? '',
  session_id: sessionId,
  seed: Math.floor(Math.random() * 9999999999)
} }];

const item = $input.first();
const agentData = $('Estrai JSON dall\'agente').first().json;
const sessionId = agentData.session_id;
const objectName = agentData.object_name;
const seed = agentData.seed;

// Il nodo comfyui mason276752 restituisce le immagini come binary
// La chiave binary può essere 'data', 'image', o il filename
const binaryKeys = Object.keys(item.binary ?? {});
console.log('Binary keys disponibili da FLUX:', JSON.stringify(binaryKeys));
console.log('JSON da FLUX:', JSON.stringify(item.json).substring(0, 400));

if (binaryKeys.length === 0) {
  throw new Error(`Nessun binary trovato nell output FLUX. JSON: ${JSON.stringify(item.json).substring(0, 300)}`);
}

const binaryKey = binaryKeys[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const base64Image = buffer.toString('base64');

const dataUri = base64Image;

console.log(`Immagine convertita: ${Math.round(buffer.length / 1024)}KB, key: ${binaryKey}`);

return [{ json: {
  image_base64: dataUri,
  session_id: sessionId,
  object_name: objectName,
  seed: seed
} }];

const history = $input.first().json;

let latestGlb = null;
let latestTime = 0;

for (const promptId of Object.keys(history)) {
  const entry = history[promptId];
  const outputs = entry?.outputs || {};
  for (const nodeId of Object.keys(outputs)) {
    const nodeOut = outputs[nodeId];
    // Cerca sia in "meshes" che in "3d"
    const meshArray = nodeOut?.meshes || nodeOut?.['3d'] || [];
    for (const mesh of meshArray) {
      if (mesh.filename?.endsWith('.glb')) {
        const t = entry.status?.status_str === 'success'
          ? new Date(entry.status?.completed_at || 0).getTime()
          : 0;
        if (t >= latestTime) {
          latestTime = t;
          latestGlb = mesh;
        }
      }
    }
  }
}

if (!latestGlb) throw new Error('Nessun file .glb trovato');

const host = "10.54.128.46";
const port = 8000;
const glbUrl = `http://${host}:${port}/view?filename=${latestGlb.filename}&type=${latestGlb.type || 'output'}&subfolder=${latestGlb.subfolder || 'mesh'}`;

return [{
  json: {
    status: "ready",
    glb_url: glbUrl,
    object_name: $input.first().json.object_name || "Object",
    session_id: $input.first().json.session_id || "unknown",
    message: "Oggetto generato con successo!"
  }
}];

